function dfs(graph, start) {
  const visited = new Set();
  const order = [];
  const traverse = (node) => {
    visited.add(node);
    order.push(node);
    for (const next of graph[node] || []) {
      if (!visited.has(next)) traverse(next);
    }
  };
  traverse(start);
  return order;
}

