def dfs(graph, start, visited=None, order=None):
    if visited is None:
        visited, order = set(), []
    visited.add(start)
    order.append(start)
    for nb in graph.get(start, []):
        if nb not in visited:
            dfs(graph, nb, visited, order)
    return order

